function qaParallel($accounts){
    $jobs=array();$start=microtime(true)+1.0;
    foreach($accounts as $account){$pipes=array();$p=proc_open(array(PHP_BINARY,__DIR__.'/worker.php',$account,(string)QA::$now,(string)$start,'1'),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes);if(!is_resource($p))throw new RuntimeException('Cannot start concurrency worker');fclose($pipes[0]);$jobs[]=array($p,$pipes);}
    $results=array();foreach($jobs as $job){list($p,$pipes)=$job;$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($p);qaEqual($code,0,'concurrent worker succeeds '.$stderr);$result=json_decode(trim($stdout),true);qaAssert(is_array($result)&&!empty($result['ok']),'worker returned actual successful process');$results[]=$result;}return $results;
}
