qaCase('expiry batch sees a real last-day sign committed after its earlier read',function(){
    qaReset();qaCampaign();qaBoundPair();qaSign('qa-B');qaHost()->v150ProcessUser('qa-B');qaUser(3,'qa-C','qa-A');pdo_insert('sage_dksy_v11_relation_audit',array('uniacid'=>1,'user_id'=>3,'new_inviter_id'=>1,'action'=>'new_bind','result'=>'ok','created_at'=>qaDay()+4000));qaSign('qa-C');qaHost('qa-C')->v150ProcessUser('qa-C');
    $lastEligibleDay=qaDay()+6*86400;QA::$now=qaDay()+7*86400+60;
    $marker=__DIR__.'/.rr-barrier-'.bin2hex(random_bytes(4));$p=null;$pipes=array();
    QA::$pdo->beginTransaction();pdo_fetch('SELECT id FROM '.tablename('sage_dksy_user').' WHERE id=3 FOR UPDATE');qaSign('qa-C',$lastEligibleDay);
    try{
        $p=proc_open(array(PHP_BINARY,__DIR__.'/rr-worker.php',(string)QA::$now,$marker),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes);qaAssert(is_resource($p),'RR worker started');fclose($pipes[0]);
        $limit=microtime(true)+5;while(!file_exists($marker)&&microtime(true)<$limit)usleep(1000);qaAssert(file_exists($marker),'expiry worker reached C user lock after prior B read');$barrier=json_decode(file_get_contents($marker),true);qaAssert($barrier['prior_sign_reads']>=2,'schema probe plus prior B day count occurred');
        QA::$pdo->commit();$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($p);$p=null;qaEqual($code,0,'RR worker completed '.$stderr);qaAssert(!empty(json_decode($stdout,true)['ok']),'real engine committed');
    }finally{if(QA::$pdo->inTransaction())QA::$pdo->rollBack();if(is_resource($p)){proc_terminate($p);proc_close($p);}if(file_exists($marker))unlink($marker);}
    qaEqual(qaRow('enrollment',array('invitee_openid'=>'qa-C'))['inviter_status'],'paid','last-day sign not lost to stale RR snapshot');qaEqual(qaBalance('qa-A'),10,'qualified C reward paid');qaEqual(qaCampaignTotals(),array(0,20),'B expiry and C payment conserved');qaEqual(pdo_fetchcolumn('SELECT @@tx_isolation'),'REPEATABLE-READ','engine leaves session default unchanged');
});
